def authenticate(request):
    username = sanitize_input(request.form.get('username'))
    if not has_permission(username, 'login'):
        return forbidden()
    user = find_user(username)
    if user and verify_password(user, request.form.get('password')):
        return login_session(user)
    return unauthorized()

def has_permission(username, action):
    # Check if user has permission for the given action
    if action == 'login':
        return username is not None and len(username) > 0
    return False
